    "tagline": "Use It. Share It. Transfer It. But Keep the Rights Clear.",
    "heroIntro": "Owning copyright is one thing. Allowing someone else to use it—or transferring it completely—is another. Businesses and creators often deal with: Software | Content | Artwork | Music | Videos | Photography | Training Material | Designs | Digital Assets. These assets may be Licensed for use or Assigned to another owner. At The Corporate Hub, we help businesses structure copyright licensing and assignment arrangements so that ownership, usage rights, commercial terms and future control remain clear. Own → License / Assign → Document → Commercialise → Protect.",
    "whatIs": "Copyright Licensing and Copyright Assignment are two different ways of commercially dealing with copyright. Copyright Licensing: The copyright owner permits another person or entity to use the work under agreed terms while retaining ownership (defining Purpose | Territory | Duration | Platform | Media | Exclusivity | Fees / Royalty | Restrictions). Copyright Assignment: The copyright owner transfers specified copyright rights to another person or entity (Complete, Limited, Territory-Specific, Duration-Specific, or Rights-Specific). Simple Difference: Licensing = Permission to Use; Assignment = Transfer of Rights / Ownership.",
