        "q": "What is APOB / VPOB in e-commerce?",
        "a": "Additional Place of Business (APOB) / Virtual Place of Business (VPOB) allows sellers to store inventory in Amazon FBA or Flipkart fulfillment centers located in different states by registering those warehouses under GST."
