    "whatIs": "Trademark Assignment is the formal legal transfer of ownership rights in a trademark (registered or pending) from one person/entity (Assignor) to another (Assignee). It can be executed with or without business goodwill and requires mandatory recordal on Form TM-P with the Trade Marks Registry.",
