    "faqs": [
      {
        "q": "What is corporate law compliance?",
        "a": "It means ensuring that a company's decisions, meetings, transactions, approvals, records and statutory filings comply with applicable corporate law."
      },
      {
        "q": "Is corporate law compliance the same as ROC filing?",
        "a": "No. ROC filing is only one part of the process. Corporate law compliance also includes approvals, documentation, meetings, registers and transaction review."
      },
      {
        "q": "Does every business transaction need a Board Resolution?",
        "a": "No. The requirement depends upon the nature of the transaction, authority available to management, applicable law and the company's constitutional documents."
      },
      {
        "q": "What is a related-party transaction?",
        "a": "A transaction between the company and a related party as defined under applicable law may require specific approvals, disclosures and compliance depending upon the facts."
      },
      {
        "q": "Can a company give a loan to a director or related entity?",
        "a": "Such transactions require careful review under applicable Companies Act provisions and should not be undertaken without checking restrictions, conditions and available exemptions."
      },
      {
        "q": "Can a company give guarantees or invest in another company?",
        "a": "Yes in appropriate cases, but applicable limits, approvals, disclosures and statutory requirements should be reviewed before the transaction."
      },
      {
        "q": "Are Board Meeting minutes compulsory?",
        "a": "Yes. Companies are required to maintain minutes and prescribed records of applicable meetings in accordance with the legal framework."
      },
      {
        "q": "What are statutory registers?",
        "a": "These are prescribed corporate records relating to matters such as members, directors, charges and other statutory information, depending upon applicability."
      },
      {
        "q": "Why is corporate compliance important during funding?",
        "a": "Investors may review historical approvals, share issuances, ownership, statutory registers, agreements, related-party transactions and ROC records during due diligence."
      },
      {
        "q": "Can The Corporate Hub review a proposed transaction before we execute it?",
        "a": "Yes. We can review the proposed corporate action and identify the approval, documentation, filing and ongoing compliance requirements applicable to it."
      }
    ],
    "relatedServices": [
      "roc-compliance",
      "company-annual-compliance",
      "secretarial-compliance"
    ]
