    "faqs": [
      {
        "q": "What is APEDA Registration?",
        "a": "APEDA Registration (RCMC) is the official exporter registration issued by APEDA for businesses exporting scheduled agricultural and processed food products."
      },
      {
        "q": "Is APEDA Registration mandatory for every exporter?",
        "a": "No. APEDA is relevant specifically for exporters dealing in products covered under the APEDA Act."
      },
      {
        "q": "Is IEC required before APEDA Registration?",
        "a": "Yes. A valid Import Export Code (IEC) issued by DGFT is mandatory before applying for APEDA RCMC."
      },
      {
        "q": "What is APEDA RCMC?",
        "a": "RCMC stands for Registration-Cum-Membership Certificate, establishing exporter membership with APEDA."
      },
      {
        "q": "Is APEDA required for all food exports?",
        "a": "It depends on the product. Scheduled agri/processed foods fall under APEDA; spices fall under Spices Board; tea/coffee fall under their respective boards."
      },
      {
        "q": "Is FSSAI also required for food exports?",
        "a": "Yes. Food exporters must maintain an applicable FSSAI licence alongside APEDA RCMC."
      },
      {
        "q": "Is APEDA enough to start exporting?",
        "a": "No. Exporters also require IEC, GST, AD Code registration with customs, FSSAI, testing reports, and export documentation."
      },
      {
        "q": "Which products fall under APEDA?",
        "a": "Fruits, vegetables, processed foods, cereals, rice, meat, poultry, dairy, honey, floriculture, confectionery, bakery products, and beverages."
      },
      {
        "q": "How long does APEDA registration take?",
        "a": "Typically 5 to 7 business days after submitting complete documents and IEC details."
      },
      {
        "q": "Can The Corporate Hub assist with complete export setup?",
        "a": "Yes. We handle IEC, APEDA RCMC, Spices Board, FSSAI, GST, AD Code, and export documentation."
      }
    ],
