      {
        "q": "Do I need a Cosmetic License to start a cosmetic brand?",
        "a": "It depends on your role. Manufacturing or importing cosmetics requires specific regulatory licences; a brand using an appropriately licensed third-party manufacturer requires a loan licence / agreement and label compliance check."
      },
      {
        "q": "Which law regulates cosmetics in India?",
        "a": "Cosmetics are primarily regulated under the Drugs and Cosmetics Act, 1940 and the Cosmetics Rules, 2020."
      },
      {
        "q": "Can I start a cosmetic brand through third-party manufacturing?",
        "a": "Yes. Many D2C brands use licensed contract manufacturers, subject to product testing, labelling, and regulatory requirements."
      },
      {
        "q": "Who issues a Cosmetic Manufacturing License?",
        "a": "Cosmetic manufacturing licences are issued by the respective State Licensing Authority under the Cosmetics Rules, 2020."
      },
      {
        "q": "Who handles registration of imported cosmetics?",
        "a": "Imported cosmetics are regulated by the Central Licensing Authority / CDSCO (Central Drugs Standard Control Organization) via the Sugaram portal."
      },
      {
        "q": "Is Trademark Registration the same as a Cosmetic License?",
        "a": "No. Trademark registration protects your brand name/logo, while cosmetic licensing provides regulatory permission to manufacture or import."
      },
      {
        "q": "Can cosmetics be sold online?",
        "a": "Yes, subject to product licence compliance, label declarations, GST, and marketplace brand guidelines."
      },
      {
        "q": "Can you help with cosmetic label compliance?",
        "a": "Yes. We review cosmetic labels to ensure mandatory declarations (ingredients, batch number, manufacturer/importer details, net weight) comply with Cosmetics Rules 2020."
      },
      {
        "q": "How long is a cosmetic manufacturing licence valid?",
        "a": "Under Cosmetics Rules 2020, licences remain valid perpetually subject to payment of retention fees every 5 years."
      },
      {
        "q": "Can The Corporate Hub handle end-to-end cosmetic brand setup?",
        "a": "Yes. We handle entity registration, trademark, cosmetic licensing, label review, and GST."
      }
