    "whatIs": "Tax Deducted at Source (TDS) requires specified payers to deduct tax when making specified payments (Salary, Rent, Professional Fees, Contractor Payments, Commission, Interest, Purchase of Goods, Partner Remuneration/Interest under Section 194T). TDS Consultancy covers determining applicability, correct rates/thresholds, monthly TDS deposit challans, quarterly TDS statements (Form 24Q, 26Q, 27Q), TRACES reconciliation, correction statements, and handling TDS notices.",
