    "faqs": [
      {
        "q": "Why is TDS so important for a business?",
        "a": "Because incorrect deduction, delayed payment, or reporting errors cause 1.5%/month interest, ₹200/day late fees, 30% expense disallowance, and TRACES tax demands."
      },
      {
        "q": "Does every payment require TDS?",
        "a": "No. TDS applicability depends upon payee category, payment nature, monetary threshold, and specific tax provisions."
      },
      {
        "q": "When should TDS be checked?",
        "a": "TDS must be checked at the time the transaction is booked or paid, whichever is earlier, because deduction triggers on credit."
      },
      {
        "q": "Is TDS applicable on partner remuneration?",
        "a": "Yes! Section 194T (effective 1 April 2025) requires firms/LLPs to deduct 10% TDS on partner salary, remuneration, bonus, and interest exceeding ₹20,000/year."
      },
      {
        "q": "Does Section 194T apply to LLPs?",
        "a": "Yes. Income Tax guidance explicitly applies Section 194T to partnership firms and LLPs making covered payments/credits to partners."
      },
      {
        "q": "If partner remuneration is only credited to capital account, is TDS relevant?",
        "a": "Yes! Statutory wording includes credit to the partner's capital account and triggers at the earlier of credit or payment."
      },
      {
        "q": "Can you handle monthly TDS working and quarterly returns?",
        "a": "Yes. We manage transaction-level review, monthly deposit working, quarterly return filing, and TRACES reconciliation."
      },
      {
        "q": "Can you correct an incorrectly filed TDS return?",
        "a": "Yes. We file correction statements to rectify PAN errors, section mismatches, challan mapping, or short deduction defaults."
      },
      {
        "q": "Can you help with TDS notices and outstanding demands?",
        "a": "Yes. We review TRACES demands, challans, returns, and books to file appropriate correction statements or responses."
      },
      {
        "q": "Can you advise on TDS before making a large or unusual payment?",
        "a": "Yes. Pre-transaction review prevents costly TDS defaults and expense disallowance."
      }
    ],
