export function getSubServiceDetail(slug) { if (!slug) return null; return subServiceDetailsData[slug] || null; }

export function getSubServicesByCategory(categorySlug) { if (!categorySlug) return []; return Object.values(subServiceDetailsData).filter((item, idx, self) => item.categorySlug === categorySlug && self.findIndex(t => t.id === item.id) === idx); }
